import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import FormLayout from "./FormLayout";

export default function OtpVerify() {
  const [otp, setOtp] = useState("");
  const [msg, setMsg] = useState("");
  const navigate = useNavigate();
  const mobile = localStorage.getItem("mobile");

  useEffect(() => {
    if (!mobile) navigate("/");
  }, []);

  const submit = async () => {
    try {
      const res = await axios.post(
        `http://localhost:8080/otp/verify?mobile=${mobile}&otp=${otp}`
      );
      setMsg(res.data);

      if (res.data.toLowerCase().includes("verified")) {
        setTimeout(() => navigate("/add-user"), 1000);
      }
    } catch {
      setMsg("Verification failed");
    }
  };

  return (
    <FormLayout title="OTP Verification" rightText="Secure Verification">
      <input
        className="form-control mb-3"
        placeholder="Enter OTP"
        value={otp}
        onChange={(e) => setOtp(e.target.value)}
      />
      <button className="btn btn-success w-100" onClick={submit}>
        Verify OTP
      </button>
      <p className="mt-3 text-center text-primary">{msg}</p>
    </FormLayout>
  );
}
